/* Conservative guide-based capture analysis. Detection may fail; safe margins win over tight cropping. */
window.DCBCapture=(()=>{
 const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
 function frame(video,view,guide){if(!video.videoWidth||video.readyState<2)throw Error('映像を待って、もう一度撮影してください。');const scale=Math.max(view.width/video.videoWidth,view.height/video.videoHeight),ox=(video.videoWidth*scale-view.width)/2,oy=(video.videoHeight*scale-view.height)/2;const gx=(guide.left-view.left+ox)/scale,gy=(guide.top-view.top+oy)/scale,gw=guide.width/scale,gh=guide.height/scale,pad=Math.min(gw,gh)*.06,x=Math.max(0,gx-pad),y=Math.max(0,gy-pad),w=Math.min(video.videoWidth-x,gw+pad*2),h=Math.min(video.videoHeight-y,gh+pad*2),factor=Math.min(1,1200/h,840/w);const canvas=document.createElement('canvas');canvas.width=Math.round(w*factor);canvas.height=Math.round(h*factor);canvas.getContext('2d').drawImage(video,x,y,w,h,0,0,canvas.width,canvas.height);canvas.captureGuide={x:(gx-x)*factor,y:(gy-y)*factor,w:gw*factor,h:gh*factor};return canvas;}
 function analyze(image){const canvas=document.createElement('canvas');canvas.height=240;canvas.width=Math.round(image.width/image.height*240);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0,canvas.width,canvas.height);const {width:w,height:h}=canvas,data=ctx.getImageData(0,0,w,h).data,gray=new Uint8Array(w*h);for(let i=0;i<gray.length;i++)gray[i]=.299*data[i*4]+.587*data[i*4+1]+.114*data[i*4+2];
  function boundary(vertical,low,high){const axis=vertical?w:h,other=vertical?h:w;let best={energy:0,coverage:0,pos:0};for(let p=Math.max(2,Math.round(axis*low));p<Math.min(axis-2,Math.round(axis*high));p++){let sum=0,strong=0,n=0;for(let q=Math.round(other*.15);q<other*.85;q++){const a=vertical?q*w+p:p*w+q,delta=Math.abs(gray[a+(vertical?1:w)]-gray[a-(vertical?1:w)]);sum+=delta;strong+=delta>24;n++;}const energy=sum/n,coverage=strong/n;if(energy*coverage>best.energy*best.coverage)best={energy,coverage,pos:p};}return best;}
  const left=boundary(true,0,.28),right=boundary(true,.72,1),top=boundary(false,0,.25),bottom=boundary(false,.75,1),sides=[left,right,top,bottom],rect={x:left.pos,y:top.pos,w:right.pos-left.pos,h:bottom.pos-top.pos};const ratio=rect.w/rect.h,confidence=Math.min(...sides.map(s=>s.coverage)),edgeDetected=sides.every(s=>s.energy>18&&s.coverage>.58)&&ratio>.55&&ratio<.86&&rect.w>w*.55&&rect.h>h*.65;
  const guide=image.captureGuide||{x:0,y:0,w:image.width,h:image.height},f=w/image.width,g={x:guide.x*f,y:guide.y*f,w:guide.w*f,h:guide.h*f};const detected=edgeDetected&&Math.abs(rect.x-g.x)/g.w<.04&&Math.abs(rect.y-g.y)/g.h<.04&&Math.abs(rect.x+rect.w-g.x-g.w)/g.w<.04&&Math.abs(rect.y+rect.h-g.y-g.h)/g.h<.04;const fit=detected?Math.max(0,1-(Math.abs(rect.x-g.x)+Math.abs(rect.y-g.y)+Math.abs(rect.x+rect.w-g.x-g.w)+Math.abs(rect.y+rect.h-g.y-g.h))/(2*(g.w+g.h))):0;
  let sharp=0,n=0;for(let y=Math.round(h*.15);y<h*.85;y++)for(let x=Math.round(w*.15);x<w*.85;x++){const i=y*w+x;sharp+=(gray[i-1]+gray[i+1]+gray[i-w]+gray[i+w]-4*gray[i])**2;n++;}const sharpness=Math.sqrt(sharp/n);
  // Sparse luminance samples make motion checks inexpensive and independent of edge detection.
  const signature=[];for(let y=12;y<h;y+=12)for(let x=8;x<w;x+=8)signature.push(gray[y*w+x]);
  return {detected,confidence,fit,sharpness,score:(detected?100+fit*120+Math.min(...sides.map(s=>s.energy))/255*20:0)+Math.min(12,sharpness*.25),rect:detected?{x:rect.x/f,y:rect.y/f,w:rect.w/f,h:rect.h/f}:null,signature};
 }
 function motion(a,b){if(!a||a.length!==b?.length)return Infinity;return a.reduce((sum,v,i)=>sum+Math.abs(v-b[i]),0)/a.length;}
 function best(frames){return frames.reduce((winner,item)=>!winner||item.analysis.score>winner.analysis.score?item:winner,null);}
 function trim(item){const image=item.image,r=item.analysis.rect;let x=0,y=0,w=image.width,h=image.height;if(r){const pad=Math.min(r.w,r.h)*.035;x=Math.max(0,Math.floor(r.x-pad));y=Math.max(0,Math.floor(r.y-pad));w=Math.min(image.width-x,Math.ceil(r.w+pad*2));h=Math.min(image.height-y,Math.ceil(r.h+pad*2));}const canvas=document.createElement('canvas'),factor=Math.min(1,1000/h,700/w);canvas.width=Math.round(w*factor);canvas.height=Math.round(h*factor);canvas.getContext('2d').drawImage(image,x,y,w,h,0,0,canvas.width,canvas.height);return canvas;}
 function blob(canvas){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('撮影画像を作成できませんでした。')),'image/jpeg',.9));}
 return {frame,analyze,motion,best,trim,blob};
})();
